package run.ikaros.music;
import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.when; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test; import org.springframework.transaction.reactive.TransactionalOperator; import reactor.core.publisher.Mono; import reactor.test.StepVerifier;
class PersistentMusicMetadataCorrectionServiceTest { @Test void savesManualCorrectionWithVersion(){UUID owner=UUID.randomUUID(),id=UUID.randomUUID(),track=UUID.randomUUID(),attachment=UUID.randomUUID(); MusicMetadataCandidateRepository repo=org.mockito.Mockito.mock(MusicMetadataCandidateRepository.class); TransactionalOperator tx=org.mockito.Mockito.mock(TransactionalOperator.class); MusicMetadataCandidateEntity old=new MusicMetadataCandidateEntity(id,owner,track,attachment,"Wrong","Artist","Album",null,null,null,1,1,null,"ID3",Instant.now(),Instant.now(),2L); MusicMetadataCandidateEntity saved=new MusicMetadataCandidateEntity(id,owner,track,attachment,"Correct","Artist","Album",null,null,null,1,1,null,"MANUAL",old.createdAt(),Instant.now(),3L); when(repo.findById(id)).thenReturn(Mono.just(old)); when(repo.save(any())).thenReturn(Mono.just(saved)); when(tx.transactional(any(Mono.class))).thenAnswer(i->i.getArgument(0)); StepVerifier.create(new PersistentMusicMetadataCorrectionService(repo,tx).update(owner,id,new UpdateMusicMetadataCandidateRequest("Correct","Artist","Album",null,null,null,1,1,null),2L)).expectNextMatches(v->"Correct".equals(v.title())&&"MANUAL".equals(v.source())&&v.version()==3L).verifyComplete(); } @Test void rejectsStaleVersion(){UUID owner=UUID.randomUUID(),id=UUID.randomUUID(); MusicMetadataCandidateRepository repo=org.mockito.Mockito.mock(MusicMetadataCandidateRepository.class); TransactionalOperator tx=org.mockito.Mockito.mock(TransactionalOperator.class); when(repo.findById(id)).thenReturn(Mono.just(new MusicMetadataCandidateEntity(id,owner,UUID.randomUUID(),UUID.randomUUID(),"A",null,null,null,null,null,null,null,null,"ID3",Instant.now(),Instant.now(),2L))); when(tx.transactional(any(Mono.class))).thenAnswer(i->i.getArgument(0)); StepVerifier.create(new PersistentMusicMetadataCorrectionService(repo,tx).update(owner,id,new UpdateMusicMetadataCandidateRequest("B",null,null,null,null,null,null,null,null),1L)).expectError(run.ikaros.common.ConflictException.class).verify(); } }
